// The dish-kinds catalog (kinds.json, generated by scripts/kinds/gen-kinds.js; docs/kinds-catalog.md is its review copy) and
// the shapes a meal is stored in: a slot's kinds and templates. A kind is a dish family (Idli, Dosa, Sabzi, Dal), with sub-kinds
// named the way families say them (Poriyal, Pappu, Sambar) and items, its variants. A template is one way a meal is plated:
// [Roti, Sabzi], [Rice, Sambar, Rasam, Poriyal], [Appam, Vegetable stew]. Decided rules: scripts/kinds/decided.md.
import catalogJson from "./kinds.json";
import { FREQUENCY_WORDS, type Frequency } from "./db/constants";
import type { Weekday } from "./dates";

// ── The catalog ──

/** One ingredient of a catalog item: `main` when the dish is not itself without it (mooli in mooli thepla, onion in kanda poha);
 *  else it is a garnish, tempering or add-in the dish can be made without (cashews in upma, ghee on top). Decided 21. */
export type CatalogIngredient = { name: string; main: boolean };
/** `contains` is derived from all its ingredients, `contains_main` from its main ones (scripts/kinds/ingredients.js). */
export type CatalogItem = { name: string; aka?: string[]; cuisines?: string[]; contains: string[]; contains_main: string[]; ingredients: CatalogIngredient[];
  suggest: boolean; regional?: boolean; /** Not counted for a cook's visit cap (owner decision OD6, 26 Nov): a no-cook extra (salad, cut fruit, boiled eggs) or plain paratha. */ capFree?: boolean; sub: string; diet?: string; meals?: string[] };
/** `bare`: the one dish a family means by the word alone ("dosa" is Plain dosa), or null when the word is a category that rotates through the items. */
export type CatalogSub = { name: string; aka: string[]; cuisines: string[]; meals: string[]; bare: string | null };
export type CatalogKind = { name: string; aka: string[]; cuisines: string[]; meals: string[]; staple: boolean; part: string; diet: string; bare: string | null;
  subs: CatalogSub[]; items: CatalogItem[] };
/** A word that means different dishes by region (decided 20): each meaning holds in its cuisines. */
export type RegionalMeaning = { cuisines: string[]; kind: string; sub: string | null };
export type RegionalWord = { word: string; forms: string[]; meanings: RegionalMeaning[] };
export type Catalog = { version: number; tags: string[]; parents: Record<string, string>; kinds: CatalogKind[]; notes?: string[]; regional?: RegionalWord[];
  /** Every ingredient the items name, and the content tags it brings (decided 21). */ ingredients?: Record<string, string[]> };

export const CATALOG = catalogJson as Catalog;

/** A dish's words as the catalog is matched on: lowercase, letters and digits, single spaces. */
export const norm = (s: string): string => s.toLowerCase().normalize("NFKD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, " ").trim();
/** The word and its singular ("idlis" → "idli", "pakoras" → "pakora"); matching tries both. */
const forms = (s: string): string[] => { const n = norm(s); return n.endsWith("s") && n.length > 3 ? [n, n.slice(0, -1)] : [n]; };
/** A sub-kind's names: "Poriyal/Thoran" is said as either. */
const subNames = (sb: CatalogSub): string[] => [...sb.name.split("/"), sb.name, ...sb.aka];

/** Where a family's words land in the catalog: the item when they named one, else the sub-kind or kind. `by` says what matched. */
export type DishMatch = { kind: string; sub: string | null; item: string | null; by: "item" | "sub" | "kind" };

type Index = { items: Map<string, DishMatch[]>; subs: Map<string, DishMatch[]>; kinds: Map<string, DishMatch[]> };
let index: Index | null = null;
function buildIndex(c: Catalog): Index {
  const ix: Index = { items: new Map(), subs: new Map(), kinds: new Map() };
  const add = (m: Map<string, DishMatch[]>, word: string, hit: DishMatch) => {
    const k = norm(word);
    if (!k) return;
    const list = m.get(k) ?? [];
    if (!list.some((h) => h.kind === hit.kind && h.sub === hit.sub && h.item === hit.item)) list.push(hit);
    m.set(k, list);
  };
  for (const k of c.kinds) {
    for (const w of [k.name, ...k.aka]) add(ix.kinds, w, { kind: k.name, sub: null, item: null, by: "kind" });
    // A kind of one sub-kind has no sub-kind of its own to name.
    if (k.subs.length > 1) for (const sb of k.subs) for (const w of subNames(sb)) add(ix.subs, w, { kind: k.name, sub: sb.name, item: null, by: "sub" });
    for (const it of k.items) for (const w of [it.name, ...(it.aka ?? [])]) add(ix.items, w, { kind: k.name, sub: it.sub, item: it.name, by: "item" });
  }
  return ix;
}
const ix = (): Index => (index ??= buildIndex(CATALOG));

/** Match a family's words for a dish ("aloo gobi", "poriyal", "idlis") to the catalog: an item first, then a sub-kind, then a
 *  kind, each by its name or other names, as said or as a singular. Null when nothing matches, or when the words name more than
 *  one place at the level that matched ("shaak" is both a dry and a gravy vegetable): those are left to the model. */
export function matchDish(words: string): DishMatch | null {
  // A regional word alone ("curry", "pachadi") is read in the family's context, never matched plainly (decided 20).
  if (regionalWordOf(words)) return null;
  for (const level of ["items", "subs", "kinds"] as const) {
    for (const f of forms(words)) {
      const hits = ix()[level].get(f);
      if (!hits?.length) continue;
      if (hits.length > 1) {
        // One item listed under one kind twice over is still one place; anything else is for the model to settle.
        const places = new Set(hits.map((h) => `${h.kind}|${h.sub ?? ""}|${level === "items" ? h.item : ""}`));
        return places.size === 1 ? hits[0] : null;
      }
      return hits[0];
    }
  }
  return null;
}

export const catalogKind = (name: string): CatalogKind | null => CATALOG.kinds.find((k) => norm(k.name) === norm(name)) ?? null;
let byItemName: Map<string, { kind: CatalogKind; item: CatalogItem }> | null = null;
export const catalogItem = (name: string): { kind: CatalogKind; item: CatalogItem } | null => {
  if (!byItemName) {
    byItemName = new Map();
    for (const kind of CATALOG.kinds) for (const item of kind.items) if (!byItemName.has(norm(item.name))) byItemName.set(norm(item.name), { kind, item });
  }
  return byItemName.get(norm(name)) ?? null;
};

/** The dish a bare word means: the sub-kind's when one is given and has one, else the kind's. Null for a category word (upma, sabzi,
 *  gravy: it rotates through the catalog), for a staple (its everyday item is `contentsItem`'s) and for a kind the catalog lacks. */
export function bareDish(kind: string, sub?: string | null): string | null {
  const k = catalogKind(kind);
  if (!k || k.staple) return null;
  const sb = sub ? k.subs.find((s) => subNames(s).some((n) => norm(n) === norm(sub))) : null;
  return sb?.bare ?? k.bare ?? null;
}

/** Whether a family's words for a kind or sub-kind may name its bare dish (H7): the kind's or a sub-kind's own name, or another
 *  name of it that no item's names hold. One an item holds names that family of items ("saaru": Udupi saaru is one), never the
 *  bare dish. */
export function bareWord(kind: string, words: string): boolean {
  const k = catalogKind(kind);
  if (!k) return false;
  const fs = forms(words);
  const own = [k.name, ...k.subs.flatMap((s) => [...s.name.split("/"), s.name])].map(norm);
  if (fs.some((f) => own.includes(f))) return true;
  const holds = (n: string) => fs.some((f) => ` ${norm(n)} `.includes(` ${f} `));
  return !k.items.some((it) => [it.name, ...(it.aka ?? [])].some(holds));
}

/** The meals a NEW item of this kind, sub-kind or item may be suggested at (decided 18). They never limit a family's own dish. */
export function suggestMeals(m: { kind: string; sub?: string | null; item?: string | null }): string[] {
  const k = catalogKind(m.kind);
  if (!k) return [];
  const it = m.item ? k.items.find((i) => norm(i.name) === norm(m.item!)) : null;
  if (it?.meals) return it.meals;
  const subName = it?.sub ?? m.sub;
  const sb = subName ? k.subs.find((s) => norm(s.name) === norm(subName)) : null;
  return sb?.meals ?? k.meals;
}

/** What an item contains, with each tag's family added (chicken → meat, prawn → seafood). Null for a dish not in the catalog. */
export function catalogContains(itemName: string): string[] | null {
  const hit = catalogItem(itemName);
  if (!hit) return null;
  const out = new Set(hit.item.contains);
  for (const t of hit.item.contains) for (let p = CATALOG.parents[t]; p; p = CATALOG.parents[p]) out.add(p);
  return [...out];
}

/** The items the planner may suggest as new for a kind (or one of its sub-kinds) to a family of these cuisines: `suggest` items,
 *  and a regional one only when one of its cuisines is the family's (decided 7). Staple kinds give none. */
export function suggestable(kind: string, opts: { sub?: string | null; cuisines?: readonly string[] } = {}): CatalogItem[] {
  const k = catalogKind(kind);
  if (!k || k.staple) return [];
  const fam = new Set((opts.cuisines ?? []).map(norm));
  return k.items.filter((it) => it.suggest && (!opts.sub || norm(it.sub) === norm(opts.sub))
    && (!it.regional || (it.cuisines ?? []).some((c) => fam.has(norm(c)))));
}

// ── A meal's shape, stored on its slot ──

/** One kind a slot's meals are built from. `subs`: the family's own sub-kinds of it (rotation prefers them; another sub-kind's
 *  item is a new variant). `staple`: comes every day its template has it, never rotated (roti, rice, curd). `own`: a kind only
 *  this family has (a dish with no kind in the catalog): nothing new is ever suggested for it. */
export type MealKind = { name: string; subs?: string[]; staple?: boolean; own?: boolean };
/** One part of a template: a kind or one sub-kind of it (filled from the family's items of it, then new ones). `words`: the
 *  family's own words for it ("dry sabji", "upma"), kept for the read-back and messages. `dish`: when their bare word names one
 *  dish of that kind, that dish (theirs, filled first; the rest of the kind's items are new). */
export type KindPart = { kind: string; sub?: string; words?: string; dish?: string };
/** A fixed list of the family's own dishes (nothing new suggested: a dish they named at a meal outside the catalog's meals for
 *  it, decided 18 and 19). */
export type ItemsPart = { items: string[] };
/** Linked (§5.1): the item `from` has for `kind` (and `sub`) that day; no kind = the whole plate of `from`. */
export type LinkedPart = { from: string; kind?: string; sub?: string };
export type TemplatePart = KindPart | ItemsPart | LinkedPart;
/** One way the meal is plated. `share`: how often, in the family's words' measure ("2/week", "usually"); null = spread evenly
 *  with the others. `said`: those words ("poha twice a week"). `days`: only on these days. */
export type MealTemplate = { parts: TemplatePart[]; share?: Frequency | null; said?: string | null; days?: Weekday[] | null };

export const isItemsPart = (p: TemplatePart): p is ItemsPart => "items" in p;
export const isLinkedPart = (p: TemplatePart): p is LinkedPart => "from" in p;
export const isKindPart = (p: TemplatePart): p is KindPart => "kind" in p && !("from" in p);

const isFrequency = (v: unknown): v is Frequency =>
  typeof v === "string" && ((FREQUENCY_WORDS as readonly string[]).includes(v) || /^[1-7]\/week$/.test(v));

/** What is wrong with a slot's templates, one line each; empty when they are fine. A kind no catalog has is the family's own
 *  kind; a sub-kind must be its catalog kind's; a dish of a kind part must be of that kind; a linked part names another meal of
 *  the house (`ctx.slots`), never its own (`ctx.slot`), and a whole-plate link is its template's only part. */
export function checkMealShape(templates: readonly MealTemplate[], ctx: { slot: string; slots: readonly string[] }): string[] {
  const errs: string[] = [];
  const subOk = (kind: string, sub: string) => { const cat = catalogKind(kind); return !!cat && cat.subs.some((x) => norm(x.name) === norm(sub)); };
  templates.forEach((t, i) => {
    const at = `template ${i + 1}`;
    if (!t?.parts?.length) { errs.push(`${at}: has no parts`); return; }
    if (t.share != null && !isFrequency(t.share)) errs.push(`${at}: share ${String(t.share)} is not usually, sometimes, rarely, daily or "<n>/week"`);
    if (t.parts.length > 1 && t.parts.some((p) => isLinkedPart(p) && !p.kind)) errs.push(`${at}: a whole plate link is the template's only part`);
    for (const p of t.parts) {
      if (isItemsPart(p)) {
        if (!Array.isArray(p.items) || !p.items.length || p.items.some((x) => typeof x !== "string" || !x.trim())) errs.push(`${at}: a part of items needs their dishes' names`);
        continue;
      }
      if (isLinkedPart(p)) {
        if (norm(p.from ?? "") === norm(ctx.slot)) errs.push(`${at}: ${ctx.slot} links to itself`);
        else if (!ctx.slots.some((x) => norm(x) === norm(p.from ?? ""))) errs.push(`${at}: ${p.from} is not a meal of this house`);
        if (p.sub && (!p.kind || !subOk(p.kind, p.sub))) errs.push(`${at}: ${p.sub} is not a sub-kind of ${p.kind ?? "its link"}`);
        continue;
      }
      if (!p.kind?.trim()) { errs.push(`${at}: a part has no kind`); continue; }
      if (p.sub && !subOk(p.kind, p.sub)) errs.push(`${at}: ${p.sub} is not a sub-kind of ${p.kind}`);
      if (p.dish) {
        const m = matchDish(p.dish);
        if (m && norm(m.kind) !== norm(p.kind)) errs.push(`${at}: ${p.dish} is not a ${p.kind}`);
      }
    }
  });
  return errs;
}

/** The kinds a meal has, derived each run from its templates, never stored: staple from the catalog, own = not a catalog kind,
 *  subs = the sub-kinds its parts name. A linked part's kind is the other meal's, not this one's. */
export function mealKinds(templates: readonly MealTemplate[]): MealKind[] {
  const out = new Map<string, MealKind>();
  for (const t of templates) for (const p of t.parts) {
    if (!isKindPart(p)) continue;
    const cat = catalogKind(p.kind);
    const k = out.get(norm(p.kind)) ?? { name: p.kind, ...(cat?.staple ? { staple: true } : {}), ...(cat ? {} : { own: true }) };
    if (p.sub && !k.subs?.some((x) => norm(x) === norm(p.sub!))) k.subs = [...(k.subs ?? []), p.sub];
    out.set(norm(p.kind), k);
  }
  return [...out.values()];
}

// ── For the setup: a sub-kind by the family's words, and an item's contents in the planner's tags ──

/** A kind's sub-kind as the catalog names it, from either half of its name or another name of it ("Thoran" is
 *  "Poriyal/Thoran"); null when it is none of the kind's. */
export function catalogSub(kind: string, words: string | null | undefined): string | null {
  const k = catalogKind(kind);
  if (!k || !words) return null;
  return k.subs.find((sb) => subNames(sb).some((w) => norm(w) === norm(words)))?.name ?? null;
}

/** The tags the catalog answers for every one of its items, in the planner's words: every catalog tag, and the planner's own
 *  families of them (meat, red_meat). An item has a tag of these or does not: the catalog leaves none unknown. */
export const PLANNER_READ_TAGS: string[] = [...new Set([...CATALOG.tags, "meat", "red_meat"])];
/** The planner's tag families (db/constants TAG_PARENT): a catalog tag adds these. Seafood is the planner's fish; peanuts are nuts. */
const PLANNER_PARENTS: Record<string, string[]> = { chicken: ["meat"], mutton: ["meat", "red_meat"], pork: ["meat", "red_meat"],
  beef: ["meat", "red_meat"], prawn: ["fish"], peanut: ["nuts"] };

/** Catalog tags in the planner's words, each with the planner's families of it. */
const asPlannerTags = (tags: readonly string[]): string[] => {
  const out = new Set<string>();
  for (const t of tags) { out.add(t); for (const p of PLANNER_PARENTS[t] ?? []) out.add(p); }
  return [...out];
};
/** An item's contents as the planner's tags (egg, meat, fish, onion_garlic, nuts, peanut, sugar, white_rice, dairy and the
 *  catalog's own: chicken, prawn, coconut, ...): `contains` from all its ingredients, `main` from its main ones (decided 21:
 *  a rule broken only by an ingredient it can be made without is a note, not a block), and the tags that answer covers
 *  (`read`, every one in PLANNER_READ_TAGS: the catalog leaves none unknown). Null for a dish not in the catalog: its
 *  contents are read by the model. */
export function plannerTags(itemName: string): { contains: string[]; main: string[]; read: string[] } | null {
  const hit = catalogItem(itemName);
  if (!hit) return null;
  return { contains: asPlannerTags(hit.item.contains), main: asPlannerTags(hit.item.contains_main), read: PLANNER_READ_TAGS };
}

/** A catalog item's ingredients, each with the planner's tags it brings (cashews: nuts; peanuts: peanut and nuts; onion:
 *  onion_garlic and root_veg), main or one the dish can be made without. Null for a dish not in the catalog. */
export function catalogIngredients(itemName: string): { name: string; main: boolean; tags: string[] }[] | null {
  const hit = catalogItem(itemName);
  if (!hit) return null;
  return hit.item.ingredients.map((x) => ({ name: x.name, main: x.main, tags: asPlannerTags(CATALOG.ingredients?.[x.name] ?? []) }));
}

/** The catalog item a dish is, for its contents: the item its words name, or for a staple named by its kind alone ("Rice",
 *  "Roti", "Curd") the kind's everyday item (Steamed rice, Phulka, Curd). Null otherwise. */
const contentsMemo = new Map<string, string | null>();
export function contentsItem(words: string | null | undefined): string | null {
  if (!words) return null;
  if (contentsMemo.has(words)) return contentsMemo.get(words)!;
  const out = contentsItemOf(words);
  contentsMemo.set(words, out);
  return out;
}
function contentsItemOf(words: string): string | null {
  const direct = catalogItem(words);
  if (direct) return direct.item.name;
  const m = matchDish(words);
  if (m?.by === "item") return m.item;
  const k = m?.by === "kind" ? catalogKind(m.kind) : null;
  return k?.staple ? k.items[0]?.name ?? null : null;
}

// ── Words that mean different dishes by region (decided 20) ──

const BROAD_REGIONS = ["south", "north", "west", "east", "central", "northeast"];
/** The regional word these words are, alone ("curry", "a kura", "curries"); null for any other words. */
export function regionalWordOf(words: string): RegionalWord | null {
  const fs = forms(words.replace(/^\s*(a|an|some|any|one)\s+/i, ""));
  return (CATALOG.regional ?? []).find((r) => r.forms.some((f) => fs.includes(norm(f)))) ?? null;
}
/** A dish named with a regional word ("dondakaya curry", "tomato pachadi", "kura beans"): the word and the rest of the name (its
 *  vegetable or base). Null when the name holds none, or is the word alone. */
export function regionalIn(words: string): { word: RegionalWord; base: string } | null {
  const ws = norm(words).split(" ").filter(Boolean);
  if (ws.length < 2) return null;
  for (const [w, rest] of [[ws[ws.length - 1], ws.slice(0, -1)], [ws[0], ws.slice(1)]] as const) {
    const r = regionalWordOf(w);
    if (r) return { word: r, base: rest.join(" ") };
  }
  return null;
}
/** What a regional word means for a family of these cuisines: the one meaning their narrow cuisines (Tamil, Andhra) name, else
 *  the one their broad regions name. Null when their cuisines name none, or more than one (the region is not clear). */
export function regionalMeaning(word: RegionalWord, cuisines: readonly string[]): RegionalMeaning | null {
  const fam = cuisines.map(norm);
  const narrow = fam.filter((c) => !BROAD_REGIONS.includes(c)), broad = fam.filter((c) => BROAD_REGIONS.includes(c));
  const by = (cs: string[]) => {
    const hits = word.meanings.filter((m) => m.cuisines.some((c) => cs.includes(norm(c))));
    return new Set(hits.map((m) => `${m.kind}|${m.sub ?? ""}`)).size === 1 ? hits[0] : hits.length ? "many" : null;
  };
  const n = narrow.length ? by(narrow) : null;
  if (n === "many") return null;
  if (n) return n;
  const b = broad.length ? by(broad) : null;
  return b && b !== "many" ? b : null;
}
/** A dish named with a regional word, placed by its meaning and its base: the meaning's kind and sub-kind, and the catalog item
 *  of that sub-kind (else kind) whose name holds the base, when exactly one does ("dondakaya curry" in an Andhra home is the
 *  Vepudu item "Dondakaya vepudu"). Null when the base is a dish of another kind (a paneer or chicken curry is no vegetable). */
export function regionalDish(base: string, m: RegionalMeaning): DishMatch | null {
  const k = catalogKind(m.kind);
  if (!k) return null;
  // The base is a vegetable or fruit (the catalog names it not, or as a vegetable dish, a salad or fruit), or a dish of the
  // meaning's own kind (its sub-kind then kept: a paneer curry in a North Indian home is a paneer gravy).
  const b = matchDish(base);
  if (b && !["Sabzi", "Salad", "Fruit"].includes(b.kind) && b.kind !== k.name) return null;
  const sub = b && b.kind === k.name && b.sub ? b.sub : m.sub ?? (k.subs.length === 1 ? k.subs[0].name : null);
  const bw = norm(base).split(" ");
  const holds = (it: CatalogItem) => [it.name, ...(it.aka ?? [])].some((w) => { const ws = norm(w).split(" "); return bw.every((x) => ws.includes(x)); });
  const hit = k.items.filter((it) => (!sub || norm(it.sub) === norm(sub)) && holds(it));
  return hit.length === 1 ? { kind: k.name, sub: hit[0].sub, item: hit[0].name, by: "item" } : { kind: k.name, sub, item: null, by: "sub" };
}
